/*
 * ENVIRONMENT 09 / ORGANIC WASTE TO COMPOST CYCLE  (REVISED)
 * Pure Canvas 2D. No external libraries, assets, DOM, or scheduling calls.
 * Entry point: draw(ctx, time, width, height). Time is expressed in SECONDS.
 * 25 seconds / one continuously active scene / seamless loop / 16:9.
 * Responsive master: 3840 x 2160 at 60 fps; also supports FHD and 2K.
 * Master video export target: 100,000,000 bits/second (100 Mbps).
 * The host video encoder must set bitrate; drawing code cannot configure it.
 * Pure #00FF00 chroma background. No green-toned foregrounds or glow.
 *
 * REVISION NOTES
 * - Layout: five stations on one 1340px-wide row with identical 96px gaps,
 *   one shared floor line (y = 722), one shared conveyor line (y = 556),
 *   one label row, and every station centered on its own axis.
 * - Motion: every moving thing runs an INTEGER number of cycles per 25s loop,
 *   so the loop is seamless. Rotations are constant speed (mechanical),
 *   swaying parts use pure sine (natural ease-in / ease-out at both ends).
 * - All conveyors share one belt speed. Tread, cargo and soil grains are
 *   driven from that same travel value, so nothing slips or drifts.
 * - Cargo only appears / disappears behind opaque housings (or via smooth
 *   alpha fade inside the screen window), never by popping in view.
 * - Every shape is built from symmetric, rigid geometry. Nothing is scaled,
 *   squashed or stretched while moving; only rotated or translated.
 */

function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  // ---------------------------------------------------------------- timing
  const DURATION = 25;
  const TAU = Math.PI * 2;
  const mod = (a, b) => ((a % b) + b) % b;
  const loopT = mod(time, DURATION);
  const progress = loopT / DURATION;                    // 0 -> 1, seamless
  const turns = (n) => TAU * n * progress;              // n whole turns per loop
  const smooth = (e0, e1, x) => {                       // smoothstep, either direction
    const k = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
    return k * k * (3 - 2 * k);
  };

  const unit = Math.min(width / 1600, height / 900);
  const C = {
    ink: '#182B46', inkSoft: '#304A68', blue: '#4469BD', blueMid: '#5B7ECC',
    blueLight: '#89A7E1', bluePale: '#CFDCF4', ivory: '#FFF4DE', paper: '#F0E5D3',
    violet: '#8970B3', violetLight: '#B6A2D1', coral: '#DC8067', coralDark: '#B35C4F',
    gold: '#E9B454', goldLight: '#F7D38D'
  };
  const FONT = 'Arial, "DejaVu Sans", Helvetica, sans-serif';

  // ------------------------------------------------------- canvas hygiene
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'transparent';
  ctx.filter = 'none';
  if (!(unit > 0)) { ctx.restore(); return; }
  ctx.translate((width - 1600 * unit) / 2, (height - 900 * unit) / 2);
  ctx.scale(unit, unit);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.setLineDash([]);

  // --------------------------------------------------------- layout grid
  const FLOOR = 722;          // every machine stands on this line
  const BELT_Y = 556;         // shared height of the horizontal conveyors
  const CX = { collect: 202, shred: 450, compost: 796, screen: 1134, reuse: 1386 };

  // --------------------------------------------- shared conveyor kinematics
  // One belt speed for the whole plant: RING_LEN * RING_LOOPS / 25 = 31.68 px/s.
  const PITCH = 24;                       // tread spacing (792 / 24 = 33 whole pitches)
  const RING_N = 6, RING_GAP = 44;        // cargo spacing
  const RING_LEN = RING_N * RING_GAP;     // 264 px closed ring
  const RING_LOOPS = 3;                   // ring revolutions per loop
  const travel = RING_LEN * RING_LOOPS * progress;

  // ----------------------------------------------------------- primitives
  function rounded(x, y, w, h, r, fill, stroke, lw) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2.5; ctx.stroke(); }
  }

  function poly(points, fill, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2.5; ctx.stroke(); }
  }

  function ellipse(x, y, rx, ry, fill, stroke, lw) {
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2.5; ctx.stroke(); }
  }

  function line(points, color, lw) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = lw || 2.5;
    ctx.stroke();
  }

  function text(value, x, y, size, color, weight, align, maxWidth) {
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'middle';
    let fs = size;
    ctx.font = (weight || 500) + ' ' + fs + 'px ' + FONT;
    if (maxWidth) {
      const measured = ctx.measureText(value).width;
      if (measured > maxWidth) {
        fs *= maxWidth / measured;
        ctx.font = (weight || 500) + ' ' + fs + 'px ' + FONT;
      }
    }
    ctx.fillStyle = color;
    ctx.fillText(value, x, y);
  }

  // Label pill: width follows the text so padding is identical everywhere.
  function label(cx, y, value) {
    ctx.font = '700 13px ' + FONT;
    const w = Math.max(132, Math.ceil(ctx.measureText(value).width) + 40);
    rounded(cx - w / 2, y, w, 30, 9, C.ivory, C.ink, 2);
    text(value, cx, y + 15, 13, C.ink, 700, 'center');
  }

  // Machine leg; its base plate always ends exactly on the floor line.
  function foot(x, top, w) {
    rounded(x - w / 2, top, w, FLOOR - top - 4, 4, C.inkSoft, C.ink, 2);
    rounded(x - w / 2 - 8, FLOOR - 10, w + 16, 10, 3, C.ink);
  }

  // Symmetric leaf (both halves identical) anchored at its base point.
  function leaf(x, y, length, spread, angle, color) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
    ctx.beginPath(); ctx.moveTo(0, 0);
    ctx.bezierCurveTo(length * 0.28, -spread, length * 0.78, -spread * 0.8, length, 0);
    ctx.bezierCurveTo(length * 0.78, spread * 0.8, length * 0.28, spread, 0, 0);
    ctx.closePath(); ctx.fillStyle = color; ctx.fill();
    ctx.strokeStyle = C.ink; ctx.lineWidth = 2.2; ctx.stroke();
    line([[4, 0], [length - 7, 0]], C.inkSoft, 1.4);
    ctx.restore();
  }

  function food(x, y, kind, angle) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
    if (kind % 3 === 0) {
      ctx.beginPath(); ctx.moveTo(-11, -5);
      ctx.quadraticCurveTo(0, 12, 12, -5); ctx.lineTo(9, -8);
      ctx.quadraticCurveTo(0, 3, -8, -8); ctx.closePath();
      ctx.fillStyle = C.goldLight; ctx.fill();
      ctx.strokeStyle = C.ink; ctx.lineWidth = 1.7; ctx.stroke();
    } else if (kind % 3 === 1) {
      leaf(-10, 1, 22, 8, 0, C.blueLight);
    } else {
      poly([[-10, 6], [-7, -9], [8, -6], [12, 4], [1, 9]], C.coral, C.ink, 1.7);
      line([[-2, -3], [3, 2]], C.coralDark, 1.3);
    }
    ctx.restore();
  }

  // Round wheel with three spokes. rotation = 0 for fixed casters.
  function roller(x, y, radius, rotation, fill, spoke) {
    ellipse(x, y, radius, radius, fill, C.ink, 2.5);
    ctx.save(); ctx.translate(x, y); ctx.rotate(rotation);
    for (let i = 0; i < 3; i++) {
      const a = i * TAU / 3;
      line([[0, 0], [Math.cos(a) * radius * 0.68, Math.sin(a) * radius * 0.68]], spoke || C.inkSoft, 2);
    }
    ctx.restore();
    ellipse(x, y, 3.4, 3.4, C.ink);
  }

  // Shredder gear: 8 equal trapezoid teeth, one index mark so the turn reads.
  function cutter(x, y, rotation) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(rotation);
    ctx.beginPath();
    for (let k = 0; k < 8; k++) {
      const a = k * TAU / 8;
      const p = [[a - 0.23, 19.5], [a - 0.11, 24], [a + 0.11, 24], [a + 0.23, 19.5]];
      for (let j = 0; j < 4; j++) {
        const px = Math.cos(p[j][0]) * p[j][1], py = Math.sin(p[j][0]) * p[j][1];
        if (!k && !j) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
    }
    ctx.closePath(); ctx.fillStyle = C.blue; ctx.fill();
    ctx.strokeStyle = C.ink; ctx.lineWidth = 2.1; ctx.stroke();
    line([[0, 0], [16, 0]], C.bluePale, 3);
    ellipse(0, 0, 8, 8, C.goldLight, C.ink, 1.8);
    ctx.restore();
  }

  // ---------------------------------------------------------- cargo glyphs
  // Each glyph is a rigid group drawn in the belt's own frame (x along the
  // belt, y across it), so it rides flat on the belt and never deforms.
  function foodItem(s, i) {
    ctx.save(); ctx.translate(s, -11);
    food(0, 0, i, ((i % 3) - 1) * 0.12);
    ctx.restore();
  }
  function chipItem(s, i) {
    const pts = [[-7, 0, 0.2], [0, -1, -0.25], [7, 0, 0.15], [-3.5, -6, -0.1], [3.5, -6, 0.3]];
    ctx.save(); ctx.translate(s, -8);
    for (let k = 0; k < pts.length; k++) {
      ctx.save(); ctx.translate(pts[k][0], pts[k][1]); ctx.rotate(pts[k][2]);
      rounded(-4, -2.6, 8, 5.2, 2, (k + i) % 2 ? C.coral : C.goldLight, C.ink, 1.1);
      ctx.restore();
    }
    ctx.restore();
  }
  function granuleItem(s, i) {
    const pts = [[-6.5, 0], [0, 0], [6.5, 0], [-3.2, -5.6], [3.2, -5.6]];
    ctx.save(); ctx.translate(s, -7);
    for (let k = 0; k < pts.length; k++) {
      ellipse(pts[k][0], pts[k][1], 3.6, 3, (k + i) % 2 ? C.coralDark : C.gold, C.ink, 1.1);
    }
    ctx.restore();
  }

  // ---------------------------------------------------------------- belt
  // Both ends sit inside opaque housings that are drawn afterwards, so
  // cargo and tread enter and leave behind solid walls.
  function belt(a, b, drawItem) {
    const dx = b[0] - a[0], dy = b[1] - a[1], len = Math.hypot(dx, dy);
    ctx.save(); ctx.translate(a[0], a[1]); ctx.rotate(Math.atan2(dy, dx));
    rounded(-12, -14, len + 24, 28, 14, C.ink);
    rounded(-9, -11, len + 18, 22, 11, C.bluePale);
    ctx.save();
    rounded(-9, -11, len + 18, 22, 11, null); ctx.clip();
    ctx.lineCap = 'butt';
    ctx.setLineDash([3, PITCH - 3]);
    ctx.lineDashOffset = -mod(travel, PITCH);
    line([[-PITCH * 2, 0], [len + PITCH * 2, 0]], C.blueMid, 16);
    ctx.setLineDash([]); ctx.lineDashOffset = 0; ctx.lineCap = 'round';
    ctx.restore();
    for (let i = 0; i < RING_N; i++) {
      const s = mod(i * RING_GAP + travel, RING_LEN);
      if (s <= len) drawItem(s, i);
    }
    ctx.restore();
  }

  // ======================================================= TITLE BLOCK
  rounded(130, 96, 50, 40, 10, C.goldLight, C.ink, 2.5);
  text('09', 155, 116, 19, C.ink, 700, 'center');
  text('ORGANIC WASTE TO COMPOST CYCLE', 198, 116, 30, C.ink, 700, 'left', 1270);
  text('Collect, shred, compost and screen organic material for reuse.', 198, 152, 16, C.ink, 500, 'left', 1220);

  // ============================================================ FLOOR SLAB
  const slab = () => rounded(100, 700, 1400, 96, 22);
  slab(); ctx.fillStyle = C.bluePale; ctx.fill();
  ctx.save(); slab(); ctx.clip();
  ctx.fillStyle = C.paper; ctx.fillRect(100, 700, 1400, 44);
  line([[100, 744], [1500, 744]], C.ink, 3);
  ctx.restore();
  rounded(100, 700, 1400, 96, 22, null, C.ink, 3);

  // ============================================================ CONVEYORS
  // Station geometry (x ranges, 96px gaps):
  //   container 130-274 | shredder 370-530 | drum 626-966 | screen 1062-1206 | planter 1302-1470
  belt([236, 570], [432, 392], foodItem);       // container -> shredder hopper
  belt([510, BELT_Y], [646, BELT_Y], chipItem);   // shredder -> drum
  belt([946, BELT_Y], [1082, BELT_Y], granuleItem); // drum -> screen
  belt([1186, 618], [1346, 684], granuleItem);  // screen -> planter

  // ============================================ 1 / FOOD WASTE CONTAINER
  const cx1 = CX.collect;
  roller(cx1 - 36, 705, 17, 0.5, C.inkSoft, C.blueMid);
  roller(cx1 + 36, 705, 17, 0.5, C.inkSoft, C.blueMid);
  rounded(130, 506, 144, 188, 14, C.ivory, C.ink, 3);
  rounded(124, 490, 156, 16, 6, C.coral, C.ink, 2.5);        // lid
  rounded(cx1 - 18, 476, 36, 14, 5, C.ivory, C.ink, 2.1);    // lid handle
  rounded(cx1 - 52, 541, 104, 80, 9, C.bluePale, C.ink, 2.3); // cut-away window
  food(cx1 - 32, 563, 0, -0.12); food(cx1, 563, 1, 0); food(cx1 + 32, 563, 2, 0.12);
  food(cx1 - 16, 598, 2, 0.1); food(cx1 + 16, 598, 0, -0.1);
  text('ORGANIC', cx1, 657, 13, C.ink, 700, 'center', 96);

  // ===================================================== 2 / SHREDDER
  const cx2 = CX.shred;
  foot(cx2 - 48, 606, 20); foot(cx2 + 48, 606, 20);
  rounded(370, 414, 160, 206, 12, C.ivory, C.ink, 3);
  poly([[352, 346], [548, 346], [516, 414], [384, 414]], C.bluePale, C.ink, 3); // hopper
  rounded(344, 332, 212, 15, 5, C.coral, C.ink, 2.5);                         // hopper rim
  line([[371.6, 360], [391.3, 402]], C.blueMid, 2.3);
  line([[528.4, 360], [508.7, 402]], C.blueMid, 2.3);
  rounded(cx2 - 65, 442, 130, 84, 9, C.bluePale, C.ink, 2.3);                 // gear window
  cutter(cx2 - 31, 484, turns(6));                                            // counter-rotating,
  cutter(cx2 + 31, 484, -turns(6) + Math.PI);                                 // mirror-symmetric
  rounded(cx2 - 58, 546, 116, 20, 6, C.coral, C.ink, 2);                      // discharge slot
  for (let i = 0; i < 5; i++) line([[cx2 - 44 + i * 22, 551], [cx2 - 44 + i * 22, 561]], C.coralDark, 1.8);
  rounded(cx2 - 52, 586, 104, 14, 5, C.paper, C.ink, 1.8);

  // ================================================ 3 / COMPOST DRUM
  const dX = 626, dY = 432, dW = 340, dH = 180, cx3 = CX.compost;
  for (const x of [cx3 - 90, cx3 + 90]) foot(x, 640, 18);
  roller(cx3 - 90, 629, 17, -turns(3), C.blueLight);
  roller(cx3 + 90, 629, 17, -turns(3), C.blueLight);
  rounded(dX, dY, dW, dH, 60, C.ivory, C.ink, 3);
  for (const x of [dX + 16, dX + dW - 16]) {
    line([[x, 464], [x, 580]], C.inkSoft, 3);
    ellipse(x, 470, 3, 3, C.ink); ellipse(x, 574, 3, 3, C.ink);
  }
  rounded(662, 454, 268, 136, 26, C.bluePale, C.ink, 2.5);                    // sectional window
  ctx.save(); rounded(665, 457, 262, 130, 23, null); ctx.clip();
  line([[665, 522], [927, 522]], C.inkSoft, 7);                               // shaft
  ctx.save(); ctx.translate(cx3, 522); ctx.rotate(turns(4));                  // mixer
  for (let i = 0; i < 4; i++) {
    ctx.save(); ctx.rotate(i * TAU / 4);
    poly([[8, -6], [44, -9], [44, 9], [8, 6]], C.blue, C.ink, 2);
    ctx.restore();
  }
  ctx.restore();
  ellipse(cx3, 522, 10, 10, C.goldLight, C.ink, 2.3);
  // Soil: a slow travelling wave of 1.6px, entering and leaving at belt level.
  ctx.beginPath(); ctx.moveTo(660, 592);
  for (let x = 660; x <= 932; x += 4) ctx.lineTo(x, BELT_Y + Math.sin(turns(2) + x * 0.04) * 1.6);
  ctx.lineTo(932, 592); ctx.closePath();
  ctx.fillStyle = C.coralDark; ctx.fill();
  // Grains flow left -> right at exactly belt speed and fade at the window ends.
  for (let i = 0; i < 14; i++) {
    const s = mod(i * (RING_LEN / 14) + travel, RING_LEN);
    const a = smooth(0, 20, s) * smooth(RING_LEN, RING_LEN - 20, s);
    ctx.globalAlpha = a;
    ellipse(665 + s, 568 + ((i * 5) % 4) * 6, 3, 2.4, i % 2 ? C.goldLight : C.coral);
  }
  ctx.globalAlpha = 1;
  ctx.restore();
  rounded(662, 454, 268, 136, 26, null, C.ink, 2.5);
  rounded(cx3 - 44, 412, 88, 20, 5, C.coral, C.ink, 2.3);                     // hatch
  for (let i = 0; i < 5; i++) line([[cx3 - 32 + i * 16, 417], [cx3 - 32 + i * 16, 427]], C.coralDark, 2);
  line([[cx3, 412], [cx3, 392]], C.inkSoft, 7);
  ellipse(cx3, 370, 22, 22, C.ivory, C.ink, 2.5);                             // gauge
  for (let i = 0; i < 5; i++) {
    const a = Math.PI * (0.85 + i * 0.325);
    line([[cx3 + Math.cos(a) * 15, 370 + Math.sin(a) * 15],
      [cx3 + Math.cos(a) * 19, 370 + Math.sin(a) * 19]], C.inkSoft, 1.6);
  }
  const needle = -Math.PI / 2 + Math.sin(turns(2)) * 0.28;                    // slow sine sweep
  line([[cx3, 370], [cx3 + Math.cos(needle) * 14, 370 + Math.sin(needle) * 14]], C.coralDark, 2.4);
  ellipse(cx3, 370, 2.8, 2.8, C.ink);

  // ===================================================== 4 / SCREEN
  const cx4 = CX.screen;
  foot(cx4 - 40, 636, 16); foot(cx4 + 40, 636, 16);
  rounded(1062, 490, 144, 160, 12, C.ivory, C.ink, 3);
  rounded(1076, 512, 116, 88, 8, C.bluePale, C.ink, 2.2);
  ctx.save(); rounded(1079, 515, 110, 82, 6, null); ctx.clip();
  const m0 = [1070, 539], m1 = [1198, 573];
  const mLen = Math.hypot(m1[0] - m0[0], m1[1] - m0[1]);
  const md = [(m1[0] - m0[0]) / mLen, (m1[1] - m0[1]) / mLen];
  const mn = [md[1], -md[0]];                                                 // up-facing normal
  line([m0, m1], C.ink, 9);
  ctx.lineCap = 'butt'; ctx.setLineDash([4, 7]);
  line([m0, m1], C.goldLight, 4.5);
  ctx.setLineDash([]); ctx.lineCap = 'round';
  for (let i = 0; i < RING_N; i++) {                                          // grains slide down the incline
    const s = mod(i * RING_GAP + travel, RING_LEN);
    if (s > mLen) continue;
    ctx.globalAlpha = smooth(10, 30, s) * smooth(124, 104, s);
    ellipse(m0[0] + md[0] * s + mn[0] * 7.5, m0[1] + md[1] * s + mn[1] * 7.5, 3.4, 3.4,
      i % 2 ? C.coralDark : C.gold, C.ink, 1.1);
  }
  ctx.globalAlpha = 1;
  ctx.restore();
  rounded(1076, 512, 9, 88, 3, C.ivory, C.ink, 1.8);
  rounded(1183, 512, 9, 88, 3, C.ivory, C.ink, 1.8);
  rounded(1076, 512, 116, 12, 4, C.coral, C.ink, 1.8);
  rounded(1076, 588, 116, 12, 4, C.coral, C.ink, 1.8);
  roller(cx4, 625, 10, turns(3), C.blueLight);

  // ============================================== 5 / SOIL REGENERATION
  const cx5 = CX.reuse;
  const sway = Math.sin(turns(2) + 0.5);                                      // 2 gentle cycles
  const sp = [[cx5, 646], [cx5, 596], [cx5 + sway * 2, 544], [cx5 + sway * 4, 490]];
  const stemAt = (t) => {
    const u = 1 - t, a = u * u * u, b = 3 * u * u * t, c = 3 * u * t * t, d = t * t * t;
    return [a * sp[0][0] + b * sp[1][0] + c * sp[2][0] + d * sp[3][0],
      a * sp[0][1] + b * sp[1][1] + c * sp[2][1] + d * sp[3][1]];
  };
  ctx.beginPath(); ctx.moveTo(sp[0][0], sp[0][1]);
  ctx.bezierCurveTo(sp[1][0], sp[1][1], sp[2][0], sp[2][1], sp[3][0], sp[3][1]);
  ctx.strokeStyle = C.ink; ctx.lineWidth = 6.5; ctx.stroke();
  ctx.strokeStyle = C.blue; ctx.lineWidth = 3.5; ctx.stroke();
  const leaves = [
    { t: 0.26, len: 58, sp: 16, ang: -0.50, col: C.blueLight },
    { t: 0.44, len: 56, sp: 16, ang: Math.PI + 0.50, col: C.violetLight },
    { t: 0.62, len: 48, sp: 14, ang: -0.56, col: C.blueLight },
    { t: 0.79, len: 42, sp: 13, ang: Math.PI + 0.58, col: C.violetLight }
  ];
  for (let k = 0; k < leaves.length; k++) {                                   // each leaf is rigid and
    const lf = leaves[k], p = stemAt(lf.t);                                   // pinned to the stem curve,
    const flex = Math.sin(turns(2) + 0.5 - 0.35 * (k + 1)) * 0.045;           // with a small phase lag
    leaf(p[0], p[1], lf.len, lf.sp, lf.ang + flex, lf.col);
  }
  leaf(sp[3][0], sp[3][1], 30, 11,
    Math.atan2(sp[3][1] - sp[2][1], sp[3][0] - sp[2][0]), C.blueLight);

  ctx.beginPath(); ctx.moveTo(cx5 - 72, 630);                                 // soil dome
  ctx.bezierCurveTo(cx5 - 60, 606, cx5 + 60, 606, cx5 + 72, 630); ctx.closePath();
  ctx.fillStyle = C.coralDark; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 2.5; ctx.stroke();
  for (let i = 0; i < 6; i++) {
    const dxg = -50 + i * 20;
